"""Final source, central library, media and existing-file preservation audit."""
from pathlib import Path
import json,hashlib,ast,re
O=Path(__file__).resolve().parent;R=O.parents[4];T=R/'.validation/run_expressive_v3_test';S=R/'blender/animation/showcase';sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
b=json.loads((T/'baseline.json').read_text());protected=[p for p in b['files'] if p not in b['allowed_metadata_changes']];changed=[p for p in protected if not (R/p).is_file() or sha(R/p)!=b['files'][p]];assert not changed,changed
entries=json.loads((S/'animation_manifest.json').read_text())['animations'];assert len(entries)==14 and entries[:13]==b['original_entries']
for e in entries:assert sha(R/e['source'])==e['source_sha256']
a=entries[-1];assert a['action']=='Run_Expressive_v3_Test' and a['status']=='pending' and a['seamless_loop'] and [a['start'],a['end'],a['closing_key'],a['fps']]==[1,20,21,30]
source=sha(O/'run_expressive_v3_review.blend');v=json.loads((O/'validation.json').read_text());c=json.loads((O/'refinement_comparison.json').read_text());show=json.loads((O/'showcase_verification.json').read_text());gui=json.loads((O/'gui_playback.json').read_text());media=json.loads((O/'media_verification.json').read_text());live=json.loads((O/'final_live_snapshot.json').read_text())
assert all(x['passed'] and x['source_sha256']==source and x['action_sha256']==a['action_sha256'] for x in [v,c,show,gui,media]) and source==a['source_sha256']
assert gui['observed_wraps']>=3 and gui['paused_restarted'] and not v['nonadjacent_overlaps'] and not v['unsupported_samples']
assert live['showcase_sha256']==show['showcase_sha256']==sha(S/'Animation_Showcase.blend') and live['manifest_sha256']==show['manifest_sha256']==sha(S/'animation_manifest.json')
assert live['active_action']==a['action'] and live['slot']==a['slot_identifier'] and live['entries']==14 and live['range']==[1,20] and live['fps']==30 and live['loop'] and live['all_action_signatures_match']
p=json.loads((O/'render_provenance.json').read_text());assert p['source_sha256']==source and p['action_sha256']==a['action_sha256'] and len(p['frames'])==120 and all(sha(O/f)==h for f,h in p['frames'].items())
package=json.loads((O/'package_provenance.json').read_text());assert package['previous_source_sha256']==b['basis_source_sha256'] and package['comparisons_original_speed_no_retiming'] and len(media['videos'])==6
for name,item in media['videos'].items():assert sha(O/item['path'])==item['sha256'] and item['fps']==30 and item['frames']==package['videos'][name]['frames']
for file in O.glob('*.py'):ast.parse(file.read_text(encoding='utf8'))
assert not [p for p in re.findall(r'\]\(([^)]+)\)',(O/'README.md').read_text()) if not p.startswith(('http','app:')) and p!='final_verification.json' and not (O/p).resolve().exists()]
assert '| Run_Expressive_v3_Test |' in (R/'docs/animation/ANIMATION_PROGRESS.md').read_text()
report={'passed':True,'source_sha256':source,'action_sha256':a['action_sha256'],'pending':True,'cadence_ratio':c['cadence_ratio'],'arm_excursion_ratio':c['arm_excursion_ratio'],'non_arm_maximum_matrix_difference':c['maximum_non_arm_matrix_difference'],'previous_run_v2_source_action_reviews_and_entry_unchanged':True,'all_thirteen_previous_entries_actions_and_sources_unchanged':True,'protected_original_files':len(protected),'changed_protected_files':changed,'godot_files_unchanged':sum('game_mobile_3d' in Path(p).parts for p in protected),'run_v2_files_unchanged':sum('run_expressive_v2_test' in Path(p).parts for p in protected),'rig_appearance_materials_and_assets_unchanged':v['appearance_rest_weights_uv_materials_images_lights_unchanged'],'support_drift_m':v['maximum_support_drift_m'],'support_height_error_m':v['maximum_support_height_error_m'],'loop_pose_error_m':v['loop_pose_error_m'],'loop_tangent_difference':v['loop_channel_tangent_difference'],'showcase_saved_reopened_switched_and_played':True,'six_original_speed_videos_decoded':True,'showcase_sha256':show['showcase_sha256'],'manifest_sha256':show['manifest_sha256'],'gameplay_status':'Blender-only Pending review. No Godot, export or runtime readiness claim.'}
(O/'final_verification.json').write_text(json.dumps(report,indent=2));print(json.dumps(report,indent=2))
